// SPEC §16 partial-restore plumbing (rolled back): the recovery tables generated by scripts/backup/lib.mjs recoveryRewriter
// accept backup rows, compare as "same" with the live rows (generated columns recomputed), and restore_records copies back.
// Usage: node supabase/tests/backup-recovery.test.mjs   (DATABASE_URL from .env.local)
import { config } from 'dotenv'; import pg from 'pg';
import { recoveryRewriter, tablesForModules } from '../../scripts/backup/lib.mjs';
config({ path: '.env.local', quiet: true });
const db = new pg.Client({ connectionString: process.env.DATABASE_URL, ssl: { rejectUnauthorized: false } });
await db.connect();
let failed = 0;
const ok = (c, m) => { console.log(c ? '✔' : '✘', m); if (!c) failed++; };
const one = async (s, p) => (await db.query(s, p)).rows[0];

await db.query('begin');
try {
  const tables = tablesForModules(['products', 'categories', 'cms']);
  const rw = recoveryRewriter(tables);
  await db.query([...rw.header(), ...rw.footer()].join('\n'));
  const n = Number((await one(`select count(*) n from pg_tables where schemaname = 'recovery' and tablename = any($1)`, [tables])).n);
  ok(n === tables.length, `recovery tables created (${n}/${tables.length})`);

  // simulate the COPY of a backup row: every non-generated column, like pg_dump does
  const cols = (await db.query(`select string_agg(quote_ident(column_name), ', ' order by ordinal_position) c from information_schema.columns
      where table_schema = 'public' and table_name = 'products' and is_generated = 'NEVER'`)).rows[0].c;
  const p = await one(`select id, title from products order by created_at limit 1`);
  await db.query(`insert into recovery.products (${cols}) select ${cols} from public.products where id = $1`, [p.id]);

  const admin = (await one(`select id from profiles where email = 'admin@demo.octopusb2b.com'`)).id;
  await db.query(`select set_config('request.jwt.claims', $1, true)`, [JSON.stringify({ sub: admin, role: 'authenticated', aal: 'aal2', amr: [{ method: 'totp', timestamp: Math.floor(Date.now() / 1000) }] })]);
  await db.query('set local role authenticated');
  const cmp = (await one(`select recovery_compare('products', array[$1]::uuid[], 5) v`, [p.id])).v;
  ok(cmp[0]?.status === 'same', `unchanged product compares as "same" (${cmp[0]?.status})`);

  await db.query('reset role');
  await db.query(`update products set title = title || ' (damaged)' where id = $1`, [p.id]);
  await db.query('set local role authenticated');
  ok((await one(`select recovery_compare('products', array[$1]::uuid[], 5)->0->>'status' s`, [p.id])).s === 'changed', 'damaged product compares as "changed"');
  const restored = Number((await one(`select restore_records('products', array[$1]::uuid[], 'agent test') n`, [p.id])).n);
  ok(restored === 1 && (await one(`select title from products where id = $1`, [p.id])).title === p.title, 'restore_records puts the backup values back');
  ok((await one(`select recovery_compare('products', array[$1]::uuid[], 5)->0->>'status' s`, [p.id])).s === 'same', 'after restore the row is "same" again');
} catch (e) {
  ok(false, `unexpected error: ${e.message}`);
} finally {
  await db.query('rollback');
  await db.end();
}
console.log(failed ? `\n${failed} check(s) failed` : '\nall backup recovery checks passed');
process.exit(failed ? 1 : 0);
